# Calculate total products
print(f"Total base items defined: {len(catalog_items)}")

products = []
for idx, item in enumerate(catalog_items, 1):
    name, cat, price, weight, desc, img_key, badge = item
    img_url = IMG_MAP.get(img_key, IMG_MAP["mix"])
    products.append({
        "id": idx,
        "sku": f"OY-{idx:03d}",
        "name": name,
        "category": cat,
        "price": float(price),
        "currency": "₪",
        "weight": weight,
        "description": desc,
        "image": img_url,
        "badge": badge,
        "in_stock": True,
        "featured": idx in [1, 2, 3, 4, 31, 32, 56, 81, 101, 121, 141, 161]
    })

# Update category counts
cat_counts = {}
for p in products:
    c = p["category"]
    cat_counts[c] = cat_counts.get(c, 0) + 1

for cat in categories:
    cat["count"] = cat_counts.get(cat["id"], 0)

with open("C:/Users/samsung/.gemini/antigravity/scratch/om-yaman-spices/data/products.json", "w", encoding="utf-8") as f:
    json.dump(products, f, ensure_ascii=False, indent=2)

with open("C:/Users/samsung/.gemini/antigravity/scratch/om-yaman-spices/data/categories.json", "w", encoding="utf-8") as f:
    json.dump(categories, f, ensure_ascii=False, indent=2)

print(f"Successfully generated {len(products)} products across {len(categories)} categories.")
for c in categories:
    print(f" - {c['name']} ({c['id']}): {c['count']} products")
